    assert.ok(errorsOf({ ...parsed, exitCode: "0" }, "RunJsonResult").some((error) => /\$\.exitCode: expected number/.test(error)));
    assert.deepEqual(errorsOf({ ...parsed, added_later: true }), [], "a member added later is ignored");
